"use client";

import { localStorageUtil } from "@/lib/utils/localStorageUtil";

import { runtimeConfig } from "@/lib/utils/runtimeConfig";
import React, { useEffect, useState, useCallback, useRef } from "react";
import styles from "@/styles/EarningLeaveTable.module.scss";
import modalStyles from "@/styles/Modal.module.scss";
import Swal from "sweetalert2";
import { fetchWithAuth } from "@/lib/utils/fetchWithAuth";
import { FaRegEdit, FaTrashAlt } from "react-icons/fa";
import { toCustomFormat, toDateInputValue } from "@/lib/utils/dateFormatUtils";

const API_BASE_URL_ADMINISTRATIVE = runtimeConfig.getApiUrl("administrative");

type EarningLeaveItem = {
  earningLeaveId?: number;
  effectivityDate?: string;
  day: string;
  earn: string;
};

type EarningLeaveHistory = {
  effectivityDate: string;
  totalRows: number;
};

export default function EarningLeaveTable() {
  const canAdd = localStorageUtil.canAdd("admin.earningleave");
  const canEdit = localStorageUtil.canEdit("admin.earningleave");
  const canDelete = localStorageUtil.canDelete("admin.earningleave");
  const [rows, setRows] = useState<EarningLeaveItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [effectivityDate, setEffectivityDate] = useState<string>("");
  const [history, setHistory] = useState<EarningLeaveHistory[]>([]);
  const [deletedRows, setDeletedRows] = useState<EarningLeaveItem[]>([]);
  const skipFetchRef = useRef(false);

  useEffect(() => {
    const today = new Date().toISOString().split("T")[0]; // yyyy-mm-dd
    setEffectivityDate(today);
  }, []);

  const fetchHistory = useCallback(async () => {
    try {
      const response = await fetchWithAuth(
        `${API_BASE_URL_ADMINISTRATIVE}/api/earningLeave/get-all`,
      );

      if (!response.ok) {
        throw new Error("Failed to fetch earning leave history");
      }

      const data: EarningLeaveItem[] = await response.json();

      const grouped = new Map<string, number>();

      data.forEach((item) => {
        if (!item.effectivityDate) return;

        const dateKey = toDateInputValue(item.effectivityDate);
        grouped.set(dateKey, (grouped.get(dateKey) ?? 0) + 1);
      });

      const historyRows: EarningLeaveHistory[] = Array.from(grouped.entries())
        .map(([effectivityDate, totalRows]) => ({
          effectivityDate,
          totalRows,
        }))
        .sort((a, b) => b.effectivityDate.localeCompare(a.effectivityDate));

      setHistory(historyRows);
    } catch (err) {
      console.error(err);
    }
  }, []);

  /* ========================
     Fetch existing data
  ========================= */
  const fetchEarningLeave = useCallback(
    async (dateToFetch?: string) => {
      const dateValue = dateToFetch || effectivityDate;
      if (!dateValue) return;

      try {
        setLoading(true);

        const response = await fetchWithAuth(
          `${API_BASE_URL_ADMINISTRATIVE}/api/earningLeave/get-all`,
        );

        if (!response.ok) {
          throw new Error("Failed to fetch earning leave");
        }

        const data: EarningLeaveItem[] = await response.json();

        const filtered = data.filter((item) =>
          item.effectivityDate?.startsWith(dateValue),
        );

        if (filtered.length > 0) {
          setRows(
            filtered.map((item) => ({
              earningLeaveId: item.earningLeaveId,
              effectivityDate: item.effectivityDate,
              day: item.day,
              earn: item.earn ?? "",
            })),
          );
        } else {
          setRows([{ day: "1", earn: "" }]);
        }
      } catch (err) {
        console.error(err);
        Swal.fire("Error", "Failed to load Earning Leave table", "error");
      } finally {
        setLoading(false);
      }
    },
    [effectivityDate],
  );

  useEffect(() => {
    if (skipFetchRef.current) {
      skipFetchRef.current = false;
      return;
    }
    fetchEarningLeave();
    fetchHistory();
  }, [fetchEarningLeave, fetchHistory]);

  /* ========================
     Handlers
  ========================= */

  const addRow = () => {
    if (!canAdd && !canEdit) return;
    setRows((prev) => [...prev, { day: String(prev.length + 1), earn: "" }]);
  };

  const removeRow = () => {
    setRows((prev) => {
      if (prev.length <= 1) return prev;
      const removed = prev[prev.length - 1];
      if (removed?.earningLeaveId && !canDelete) {
        void Swal.fire({
          icon: "warning",
          title: "Permission denied",
          text: "Deleting a saved row requires Delete permission.",
        });
        return prev;
      }
      if (removed && removed.earningLeaveId) {
        setDeletedRows((d) => [...d, removed]);
      }
      return prev.slice(0, -1);
    });
  };

  const checkExistingByEffectivityDate = async (date: string) => {
    const response = await fetchWithAuth(
      `${API_BASE_URL_ADMINISTRATIVE}/api/earningLeave/getBy/${toCustomFormat(date, false)}`,
    );

    if (!response.ok) {
      throw new Error("Failed to validate effectivity date");
    }

    const data: EarningLeaveItem[] = await response.json();
    return data;
  };

  /* ========================
     Save (Create / Update)
  ========================= */
  const handleSave = async () => {
    const editingExisting = rows.some((r) => r.earningLeaveId);
    if (editingExisting ? !canEdit : !canAdd) {
      void Swal.fire({
        icon: "warning",
        title: "Permission denied",
        text: editingExisting
          ? "You do not have permission to edit this table."
          : "You do not have permission to add this table.",
      });
      return;
    }
    if (deletedRows.length > 0 && !canDelete) {
      void Swal.fire({
        icon: "warning",
        title: "Permission denied",
        text: "Deleting saved rows requires Delete permission.",
      });
      return;
    }
    try {
      if (!effectivityDate) {
        Swal.fire("Validation", "Effectivity Date is required", "warning");
        return;
      }

      if (rows.some((r) => !r.day.trim() || !r.earn.trim())) {
        Swal.fire(
          "Validation",
          "Day(s) and Earned Leave cannot be empty",
          "warning",
        );
        return;
      }

      setLoading(true);

      // 🔍 CHECK EXISTING DATA FIRST
      const existingData =
        await checkExistingByEffectivityDate(effectivityDate);

      const isEditing = rows.some((r) => r.earningLeaveId);

      // ❌ Prevent duplicate creation
      if (!isEditing && existingData.length > 0) {
        Swal.fire({
          icon: "warning",
          title: "Duplicate Effectivity Date",
          text: "Records already exist for this Effectivity Date. Please edit the existing data instead.",
        });
        return;
      }

      const payload = rows.map((row) => ({
        ...row,
        effectivityDate: toCustomFormat(effectivityDate, false),
      }));

      const url = isEditing
        ? `${API_BASE_URL_ADMINISTRATIVE}/api/earningLeave/update`
        : `${API_BASE_URL_ADMINISTRATIVE}/api/earningLeave/create`;

      await fetchWithAuth(url, {
        method: isEditing ? "PUT" : "POST",
        body: JSON.stringify(payload),
      });

      // If there are removed rows that have persisted IDs, call deleteById endpoint
      if (deletedRows.length > 0) {
        try {
          const delPayload = deletedRows.map((r) => ({
            earningLeaveId: r.earningLeaveId,
          }));
          await fetchWithAuth(
            `${API_BASE_URL_ADMINISTRATIVE}/api/earningLeave/deleteById`,
            {
              method: "DELETE",
              body: JSON.stringify(delPayload),
            },
          );
          // clear deleted rows after successful deletion
          setDeletedRows([]);
        } catch (err) {
          console.error("Failed to delete removed rows:", err);
        }
      }

      Swal.fire("Success", "Earning Leave saved successfully", "success");

      // Refresh data by manually fetching instead of relying on effectivityDate change
      await fetchEarningLeave(effectivityDate);
      fetchHistory();
    } catch (err) {
      console.error(err);
      Swal.fire("Error", "Failed to save Earning Leave", "error");
    } finally {
      setLoading(false);
    }
  };

  /* ========================
     Clear
  ========================= */
  const handleClear = async () => {
    if (!effectivityDate) return;

    const confirm = await Swal.fire({
      text: `Clear records for ${effectivityDate}?`,
      icon: "warning",
      showCancelButton: true,
      confirmButtonText: "Clear",
    });

    if (!confirm.isConfirmed) {
      return;
    }

    try {
      Swal.fire("Cleared", "Records cleared successfully", "success");
      setRows([{ day: "1", earn: "" }]);

      fetchHistory();
    } catch (err) {
      console.error(err);
      Swal.fire("Error", "Failed to clear records", "error");
    }
  };

  const updateRow = (
    index: number,
    field: keyof EarningLeaveItem,
    value: string,
  ) => {
    setRows((prev) =>
      prev.map((row, i) => (i === index ? { ...row, [field]: value } : row)),
    );
  };

  const handleEditHistory = async (selectedDate: string) => {
    if (!canEdit) {
      void Swal.fire({
        icon: "warning",
        title: "Permission denied",
        text: "You do not have permission to edit this table.",
      });
      return;
    }
    try {
      setLoading(true);

      // Use the effectivityDate from the clicked history row
      const response = await fetchWithAuth(
        `${API_BASE_URL_ADMINISTRATIVE}/api/earningLeave/getBy/${toCustomFormat(selectedDate, false)}`,
      );

      if (!response.ok)
        throw new Error("Failed to fetch earning leave for the selected date");

      const data: EarningLeaveItem[] = await response.json();

      if (data.length > 0) {
        // Set rows first, then set the date to avoid race condition
        setRows(
          data.map((item) => ({
            earningLeaveId: item.earningLeaveId,
            effectivityDate: item.effectivityDate,
            day: item.day,
            earn: item.earn ?? "",
          })),
        );
        // Mark to skip the automatic fetch in useEffect
        skipFetchRef.current = true;
        setEffectivityDate(selectedDate);
      } else {
        setRows([{ day: "1", earn: "" }]);
        skipFetchRef.current = true;
        setEffectivityDate(selectedDate);
      }
    } catch (err) {
      console.error(err);
      Swal.fire("Error", "Failed to load selected Earning Leave", "error");
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteHistory = async (date: string) => {
    if (!canDelete) {
      void Swal.fire({
        icon: "warning",
        title: "Permission denied",
        text: "You do not have permission to delete this table.",
      });
      return;
    }
    const confirm = await Swal.fire({
      text: `Delete earning leave effective ${date}?`,
      icon: "warning",
      showCancelButton: true,
      confirmButtonText: "Delete",
    });

    if (!confirm.isConfirmed) return;

    try {
      await fetchWithAuth(
        `${API_BASE_URL_ADMINISTRATIVE}/api/earningLeave/delete/${toCustomFormat(
          date,
          false,
        )}`,
        { method: "DELETE" },
      );

      Swal.fire("Deleted", "History deleted successfully", "success");
      fetchHistory();

      if (date === effectivityDate) {
        setRows([{ day: "1", earn: "" }]);
      }
    } catch (err) {
      console.error(err);
      Swal.fire("Error", "Failed to delete history", "error");
    }
  };

  /* ========================
     Render
  ========================= */
  return (
    <div className={modalStyles.Modal}>
      <div className={modalStyles.modalContent}>
        <div className={modalStyles.modalHeader}>
          <h2 className={modalStyles.mainTitle}>Earning Leave Table</h2>
        </div>

        <div className={modalStyles.modalBody}>
          <div className={styles.EarningLeave}>
            <div className={styles.EarningLeaveTable}>
              <div className={styles.toolbar}>
                <button
                  className={styles.newButton}
                  onClick={handleSave}
                  disabled={
                    loading ||
                    (rows.some((r) => r.earningLeaveId) ? !canEdit : !canAdd)
                  }
                >
                  💾 Save
                </button>
                <button className={styles.clearButton} onClick={handleClear}>
                  ✖ Clear
                </button>
              </div>
              <div className={styles.effectivityDate}>
                <label>Effectivity Date</label>
                <input
                  type="date"
                  value={effectivityDate}
                  onChange={(e) => setEffectivityDate(e.target.value)}
                />
              </div>

              <div className={styles.tableContainer}>
                <table className={styles.earningTable}>
                  <thead>
                    <tr>
                      <th>Day(s)</th>
                      <th>Earned Leave</th>
                    </tr>
                  </thead>
                  <tbody>
                    {rows.map((row, index) => (
                      <tr key={index}>
                        <td>
                          <input
                            type="number"
                            min="0"
                            step="0.01"
                            className={styles.earnedLeaveInput}
                            value={row.day}
                            onChange={(e) =>
                              updateRow(index, "day", e.target.value)
                            }
                          />
                        </td>
                        <td>
                          <input
                            type="number"
                            min="0"
                            step="0.01"
                            className={styles.earnedLeaveInput}
                            value={row.earn}
                            onChange={(e) =>
                              updateRow(index, "earn", e.target.value)
                            }
                          />
                        </td>
                      </tr>
                    ))}

                    <tr>
                      <td colSpan={2} className={styles.addTableRow}>
                        <button
                          className={styles.myButton}
                          onClick={addRow}
                          disabled={!canAdd && !canEdit}
                        >
                          + Add
                        </button>
                        &nbsp;&nbsp;&nbsp;
                        <button
                          className={styles.myButton}
                          onClick={removeRow}
                          disabled={!canAdd && !canEdit}
                        >
                          − Remove
                        </button>
                      </td>
                    </tr>
                  </tbody>
                </table>
              </div>
              <div>&nbsp;</div>
              <div className={styles.EarningLeaveTableHistory}>
                <h3 className={styles.historyTitle}>Earning Leave History</h3>

                <table className={styles.table}>
                  <thead>
                    <tr>
                      <th>Effectivity Date</th>
                      <th>Total Rows</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {history.length === 0 && (
                      <tr>
                        <td colSpan={3} style={{ textAlign: "center" }}>
                          No history available
                        </td>
                      </tr>
                    )}

                    {history.map((item) => (
                      <tr key={item.effectivityDate}>
                        <td>{item.effectivityDate}</td>
                        <td>{item.totalRows}</td>
                        <td className={styles.actionsCell}>
                          <button
                            className={`${styles.iconButton} ${styles.editIcon}`}
                            onClick={() =>
                              handleEditHistory(item.effectivityDate)
                            }
                            disabled={!canEdit}
                          >
                            <FaRegEdit />
                          </button>
                          <button
                            className={`${styles.iconButton} ${styles.deleteIcon}`}
                            onClick={() =>
                              handleDeleteHistory(item.effectivityDate)
                            }
                            disabled={!canDelete}
                          >
                            <FaTrashAlt />
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
